package com.hau.exam.infrastructure.persistence.entity;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity@Table(name="exam_templates")public class TemplateEntity{@Id public UUID id;@Column(nullable=false)public String name;@Column(name="faculty_id",nullable=false)public String facultyId;@Column(name="matrix_id",nullable=false)public UUID matrixId;@Column(columnDefinition="text")public String header;@Column(columnDefinition="text")public String instructions;@Column(name="created_by",nullable=false)public UUID createdBy;@Column(name="created_at",nullable=false)public Instant createdAt;@Column(name="updated_at",nullable=false)public Instant updatedAt;}
